static String calc(String a, String op, String b) {
  try {
    double x = Double.parseDouble(a), y = Double.parseDouble(b);
    switch (op) {
      case "+": return "" + (x + y); case "-": return "" + (x - y); case "*": return "" + (x * y);
      case "/": if (y == 0) throw new ArithmeticException("Cannot divide by zero"); return "" + (x / y);
      default: throw new IllegalArgumentException("Unknown operator");
    }
  } catch (NumberFormatException e) { return "Enter numbers only"; }
  catch (RuntimeException e) { return e.getMessage(); }
}
